mapper.select:
select i.item_id, i.type, i.title, i.description, i.category_id, i.images, i.location, i.happen_time, i.contact, i.urgent, i.reward, i.status, i.views, i.user_id, i.create_time, c.category_name, u.user_name, u.avatar as user_avatar from item i left join category c on i.category_id = c.category_id left join user u on i.user_id = u.user_id
and i.title like concat('%', #{item.title}, '%')
and i.type = #{item.type}
and i.category_id = #{item.categoryId}
and i.status = #{item.status}
and i.urgent = #{item.urgent}
and i.user_id = #{item.userId}
and (i.title like concat('%', #{item.keyword}, '%') or i.description like concat('%', #{item.keyword}, '%') or i.location like concat('%', #{item.keyword}, '%'))
order by i.create_time desc
